js-mh-undo-redo.alternative:
const createHistory = initial => {
  let present = initial;
  const past = []; // newest last
  const undone = []; // the most recently undone last
  return {
    current: () => present,
    set(value) {
      past.push(present);
      present = value;
      undone.length = 0; // a new change starts a new branch
    },
    undo() {
      // Check the length, not the value: 0, "" and false are values too.
      if (past.length > 0) {
        undone.push(present);
        present = past.pop();
      }
      return present;
    },
    redo() {
      if (undone.length > 0) {
        past.push(present);
        present = undone.pop();
      }
      return present;
    },
  };
};

